<?php
require __DIR__ . '/../includes/bootstrap.php';
require_once __DIR__ . '/../includes/finance_lib.php';
$user = require_admin(); $t = today();
$R = resolve_range('all'); $cycleParam = get('cycle_id'); $cycleId = $cycleParam === 'none' ? -1 : (int)$cycleParam; $houseId = (int)get('house_id'); $catId = (int)get('category_id'); $qs = get('q');
$view = in_array(get('view'), ['expenses', 'revenue'], true) ? get('view') : 'overview';
[$WE, $PE] = fin_scope('e', $R, $cycleId, $houseId, $catId, $qs); [$WR, $PR] = fin_scope('e', $R, $cycleId, $houseId, $catId, $qs);
$totE = (float)val("SELECT COALESCE(SUM(e.amount),0) FROM expenses e WHERE $WE", $PE); $totR = (float)val("SELECT COALESCE(SUM(e.amount),0) FROM revenue e WHERE $WR", $PR);
$cycles = rows('SELECT c.id, c.cycle_name, c.status, c.house_id, h.house_number FROM production_cycles c JOIN houses h ON h.id = c.house_id ORDER BY c.placement_date DESC');
$houses = rows('SELECT id, house_number FROM houses ORDER BY house_number');
$cats = ['expense' => rows("SELECT * FROM finance_categories WHERE type = 'expense' AND is_active = 1 ORDER BY name"), 'revenue' => rows("SELECT * FROM finance_categories WHERE type = 'revenue' AND is_active = 1 ORDER BY name")];
$allCats = rows('SELECT * FROM finance_categories ORDER BY type, name');
$base = ['range' => $R['range'], 'from' => $R['from'], 'to' => $R['to'], 'cycle_id' => $cycleParam, 'house_id' => $houseId ?: '', 'category_id' => $catId ?: '', 'q' => $qs];
$tabUrl = fn($v) => '?' . http_build_query(array_merge($base, ['view' => $v]));
page_start('Finance', 'finance');
page_head('Finance', 'Expenses and revenue in ' . setting('currency_code', 'KHR') . '. Change the currency in Settings.', '<button class="btn btn-featured" data-modal-open="m-fin-expense">' . icon('plus', 18) . ' Add expense</button><button class="btn btn-primary btn-featured" data-modal-open="m-fin-revenue">' . icon('plus', 18) . ' Add revenue</button>');
echo range_filter_html($R, ['view' => $view, 'cycle_id' => $cycleParam, 'house_id' => $houseId ?: '', 'category_id' => $catId ?: '', 'q' => $qs], ['all' => 'All time', '30d' => 'Last 30 days', 'cycle' => 'This cycle', 'custom' => 'Custom']);
echo '<form method="get" class="filters"><input type="hidden" name="view" value="' . e($view) . '"><input type="hidden" name="range" value="' . e($R['range']) . '"><input type="hidden" name="from" value="' . e($R['from']) . '"><input type="hidden" name="to" value="' . e($R['to']) . '"><div><label>Cycle</label><select name="cycle_id" onchange="this.form.submit()"><option value="">All cycles</option><option value="none"' . ($cycleId === -1 ? ' selected' : '') . '>Unallocated (no cycle)</option>';
foreach ($cycles as $c) echo '<option value="' . $c['id'] . '"' . ($cycleId === (int)$c['id'] ? ' selected' : '') . '>' . e($c['cycle_name']) . '</option>';
echo '</select></div><div><label>House</label><select name="house_id" onchange="this.form.submit()"><option value="">All</option>'; foreach ($houses as $h) echo '<option value="' . $h['id'] . '"' . ($houseId == $h['id'] ? ' selected' : '') . '>' . e(house_label($h['house_number'])) . '</option>'; echo '</select></div><div><label>Category</label><select name="category_id" onchange="this.form.submit()"><option value="">All</option>'; foreach ($allCats as $c) echo '<option value="' . $c['id'] . '"' . ($catId == $c['id'] ? ' selected' : '') . '>' . e(ucfirst($c['type']) . ': ' . $c['name']) . '</option>'; echo '</select></div><div style="flex:2"><label>Search</label><input type="search" name="q" value="' . e($qs) . '" placeholder="Description, reference, notes"></div><button class="btn btn-primary">Search</button></form>';
echo '<div class="tabs"><a class="tab ' . ($view === 'overview' ? 'on' : '') . '" href="' . e($tabUrl('overview')) . '">Overview</a><a class="tab ' . ($view === 'expenses' ? 'on' : '') . '" href="' . e($tabUrl('expenses')) . '">Expenses</a><a class="tab ' . ($view === 'revenue' ? 'on' : '') . '" href="' . e($tabUrl('revenue')) . '">Revenue</a></div>';

if ($view === 'overview') {
    $unE = (float)val('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE cycle_id IS NULL AND txn_date BETWEEN ? AND ?', [$R['from'], $R['to']]); $unR = (float)val('SELECT COALESCE(SUM(amount),0) FROM revenue WHERE cycle_id IS NULL AND txn_date BETWEEN ? AND ?', [$R['from'], $R['to']]);
    $net = $totR - $totE;
    echo '<div class="grid g3 mb">'
        . farm_metric_card('wallet', 'Total expenses', fmt_money($totE), 'metric-rose', 'EXPENSES', e(fmt_date($R['from']) . ' – ' . fmt_date($R['to'])))
        . farm_metric_card('trend', 'Total revenue', fmt_money($totR), 'metric-green', 'REVENUE', e(fmt_date($R['from']) . ' – ' . fmt_date($R['to'])))
        . farm_metric_card('activity', 'Net result of recorded entries', ($net < 0 ? '−' : '') . fmt_money(abs($net)), $net < 0 ? 'metric-gold' : 'metric-blue', 'NET RESULT', e(fmt_date($R['from']) . ' – ' . fmt_date($R['to'])))
        . '</div>';
    $stat = []; $rowsC = rows('SELECT c.id, c.cycle_name, c.status, h.house_number, (SELECT COALESCE(SUM(amount),0) FROM expenses x WHERE x.cycle_id = c.id AND x.txn_date BETWEEN ? AND ?) ex, (SELECT COALESCE(SUM(amount),0) FROM revenue x WHERE x.cycle_id = c.id AND x.txn_date BETWEEN ? AND ?) rv FROM production_cycles c JOIN houses h ON h.id = c.house_id ORDER BY h.house_number, c.placement_date DESC', [$R['from'], $R['to'], $R['from'], $R['to']]);
    $flags = [];
    foreach ($rowsC as $c) { $f = []; if ($c['status'] !== 'active') { if ((float)$c['rv'] == 0) $f[] = 'no revenue recorded'; if ((float)$c['ex'] == 0) $f[] = 'no expenses recorded'; } else $f[] = 'still running'; $flags[$c['id']] = $f; }
    $incomplete = array_filter($flags, fn($f) => array_intersect($f, ['no revenue recorded', 'no expenses recorded']));
    echo '<div class="notice warn">' . icon('alert', 18) . '<div><strong>This is not a profit statement.</strong> ' . ($incomplete ? count($incomplete) . ' closed cycle(s) have missing expenses or revenue. ' : '') . 'Check that everything is recorded before treating the net result as actual profit.</div></div>';
    $expBy = rows("SELECT fc.name, SUM(e.amount) total, COUNT(*) n FROM expenses e JOIN finance_categories fc ON fc.id = e.category_id WHERE $WE GROUP BY fc.name ORDER BY total DESC", $PE);
    echo '<div class="grid g2 mb"><div class="card chart-bento" data-spotlight><div class="card-head"><h2>Expenses by category</h2></div>';
    if (!$expBy) echo empty_state('No expenses in this view', 'Add an expense to see the breakdown.', 'wallet'); else {
        echo '<div class="chart-box sm"><canvas id="ch-exp"></canvas></div><div class="table-wrap mt"><table><tbody>'; foreach ($expBy as $x) echo '<tr><td>' . e($x['name']) . '</td><td class="num">' . e(fmt_money($x['total'])) . '</td><td class="num muted">' . fmt_pct(pct_of($x['total'], $totE), 1) . '</td></tr>'; echo '</tbody></table></div>'; }
    echo '</div><div class="card chart-bento" data-spotlight><div class="card-head"><h2>Revenue by category</h2></div>';
    $revBy = rows("SELECT fc.name, SUM(e.amount) total FROM revenue e JOIN finance_categories fc ON fc.id = e.category_id WHERE $WR GROUP BY fc.name ORDER BY total DESC", $PR);
    if (!$revBy) echo empty_state('No revenue in this view', 'Record sales to see income here.', 'trend'); else { echo '<div class="table-wrap"><table><tbody>'; foreach ($revBy as $x) echo '<tr><td>' . e($x['name']) . '</td><td class="num">' . e(fmt_money($x['total'])) . '</td><td class="num muted">' . fmt_pct(pct_of($x['total'], $totR), 1) . '</td></tr>'; echo '</tbody></table></div>'; }
    echo '</div></div><div class="card chart-bento" data-spotlight><div class="card-head"><h2>Summary by production cycle</h2><span class="muted small">Current and previous cycles</span></div><div class="table-wrap"><table><thead><tr><th>Cycle</th><th>House</th><th class="num">Expenses</th><th class="num">Revenue</th><th class="num">Net</th><th>Data check</th></tr></thead><tbody>';
    foreach ($rowsC as $c) { $n = (float)$c['rv'] - (float)$c['ex']; echo '<tr><td><a href="' . e(url('cycles/view.php?id=' . $c['id'])) . '">' . e($c['cycle_name']) . '</a> ' . cycle_status_badge($c['status']) . '</td><td>' . e(house_label($c['house_number'])) . '</td><td class="num">' . e(fmt_money($c['ex'])) . '</td><td class="num">' . e(fmt_money($c['rv'])) . '</td><td class="num">' . ($n < 0 ? '−' : '') . e(fmt_money(abs($n))) . '</td><td class="small">' . ($flags[$c['id']] ? badge(implode(', ', $flags[$c['id']]), 'warn') : badge('Complete entries', 'success')) . '</td></tr>'; }
    echo '<tr style="background:#faf7ee"><td><strong>Unallocated</strong><div class="small muted">not linked to any cycle</div></td><td>—</td><td class="num">' . e(fmt_money($unE)) . '</td><td class="num">' . e(fmt_money($unR)) . '</td><td class="num">' . ($unR - $unE < 0 ? '−' : '') . e(fmt_money(abs($unR - $unE))) . '</td><td class="small">' . ($unE + $unR > 0 ? badge('Needs a cycle?', 'warn') : '—') . '</td></tr></tbody></table></div></div>';
    echo '<script>window.__fin = ' . json_encode(['exp' => $expBy], JSON_HEX_TAG) . ';</script>';
} else {
    $tbl = fin_table($view); $total = $view === 'revenue' ? $totR : $totE; $WW = $view === 'revenue' ? $WR : $WE; $PP = $view === 'revenue' ? $PR : $PE;
    $st = sort_state(['date' => 'e.txn_date', 'amount' => 'e.amount', 'category' => 'fc.name'], 'date');
    $pg = paginate((int)val("SELECT COUNT(*) FROM $tbl e WHERE $WW", $PP), 15);
    $list = rows("SELECT e.*, fc.name cat, c.cycle_name, h.house_number FROM $tbl e JOIN finance_categories fc ON fc.id = e.category_id LEFT JOIN production_cycles c ON c.id = e.cycle_id LEFT JOIN houses h ON h.id = COALESCE(e.house_id, c.house_id) WHERE $WW ORDER BY " . $st['sql'] . ', e.id DESC LIMIT ' . $pg['per'] . ' OFFSET ' . $pg['offset'], $PP);
    echo '<div class="card chart-bento" data-spotlight><div class="card-head"><h2>' . ($view === 'revenue' ? 'Revenue' : 'Expenses') . ' · total ' . e(fmt_money($total)) . '</h2><a class="btn btn-featured btn-sm" href="' . e(url('finance/export.php?' . http_build_query(array_merge($base, ['type' => $view])))) . '">' . icon('download', 16) . ' Export for Excel</a></div>';
    if (!$list) echo empty_state('No ' . $view . ' found', 'Use the buttons above to add the first record.', 'wallet');
    else { echo '<div class="table-wrap"><table><thead><tr>' . th_sort('Date', 'date', $st) . th_sort('Category', 'category', $st) . '<th>Description</th><th>Cycle / house</th><th>Payment</th>' . th_sort('Amount', 'amount', $st) . '<th></th></tr></thead><tbody>';
        foreach ($list as $x) { $vals = ['id' => $x['id'], 'txn_date' => $x['txn_date'], 'category_id' => $x['category_id'], 'description' => $x['description'], 'amount' => (float)$x['amount'], 'cycle_id' => $x['cycle_id'] ?? '', 'house_id' => $x['house_id'] ?? '', 'payment_method' => $x['payment_method'] ?? '', 'reference' => $x['reference'] ?? '', 'notes' => $x['notes'] ?? '', 'type' => $view === 'revenue' ? 'revenue' : 'expense'];
            echo '<tr><td class="nowrap">' . e(fmt_date($x['txn_date'])) . '</td><td>' . e($x['cat']) . '</td><td>' . e($x['description']) . ($x['reference'] ? '<div class="small muted">Ref: ' . e($x['reference']) . '</div>' : '') . '</td><td class="small">' . ($x['cycle_name'] ? e($x['cycle_name']) : badge('Unallocated', 'warn')) . ($x['house_number'] ? '<div class="muted">' . e(house_label($x['house_number'])) . '</div>' : '') . '</td><td class="small">' . e($x['payment_method'] ?? '—') . '</td><td class="num"><strong>' . e(fmt_money($x['amount'])) . '</strong></td><td class="act"><button class="btn btn-ghost btn-sm" data-fill="m-fin-' . ($view === 'revenue' ? 'revenue' : 'expense') . '" data-values=\'' . e(json_encode($vals)) . '\' data-title="Edit ' . ($view === 'revenue' ? 'revenue' : 'expense') . '">' . icon('edit', 15) . '</button> <form method="post" action="' . e(url('actions/finance.php')) . '" style="display:inline" data-confirm="Delete this ' . ($view === 'revenue' ? 'revenue' : 'expense') . ' record (' . e(fmt_money($x['amount'])) . ')? This is recorded in the audit log." data-confirm-ok="Delete">' . csrf_field() . '<input type="hidden" name="op" value="delete"><input type="hidden" name="type" value="' . ($view === 'revenue' ? 'revenue' : 'expense') . '"><input type="hidden" name="id" value="' . $x['id'] . '"><input type="hidden" name="return" value="' . e('finance/index.php?' . http_build_query(array_merge($base, ['view' => $view]))) . '"><button class="btn btn-ghost btn-sm" aria-label="Delete">' . icon('trash', 15) . '</button></form></td></tr>'; }
        echo '</tbody></table></div>' . pagination_html($pg); }
    echo '</div>';
}
foreach (['expense', 'revenue'] as $ty) {
    modal_start('m-fin-' . $ty, 'Add ' . $ty);
    echo '<form method="post" action="' . e(url('actions/finance.php')) . '">' . csrf_field() . '<input type="hidden" name="op" value="save"><input type="hidden" name="type" value="' . $ty . '"><input type="hidden" name="id" value=""><input type="hidden" name="return" value="' . e('finance/index.php?' . http_build_query(array_merge($base, ['view' => $ty === 'revenue' ? 'revenue' : 'expenses']))) . '"><div class="form-grid">';
    echo '<div class="field"><label>Date</label><input type="date" name="txn_date" value="' . $t . '" max="' . $t . '" required></div><div class="field"><label>Category</label><select name="category_id" required>'; foreach ($cats[$ty] as $c) echo '<option value="' . $c['id'] . '">' . e($c['name']) . '</option>'; echo '</select></div>';
    echo '<div class="field full"><label>Description</label><input name="description" maxlength="255" required></div><div class="field"><label>Amount (' . e(setting('currency_code', 'KHR')) . ')</label><input type="number" name="amount" min="0" step="any" required></div><div class="field"><label>Payment method (optional)</label><input name="payment_method" list="pm" maxlength="60"><datalist id="pm"><option>Cash</option><option>Bank transfer</option><option>ABA</option><option>Wing</option></datalist></div>';
    echo '<div class="field"><label>Production cycle</label><select name="cycle_id"><option value="">Not linked (unallocated)</option>'; foreach ($cycles as $c) echo '<option value="' . $c['id'] . '">' . e($c['cycle_name']) . ' (' . e(house_label($c['house_number'])) . ')</option>'; echo '</select></div><div class="field"><label>House (if no cycle)</label><select name="house_id"><option value="">None</option>'; foreach ($houses as $h) echo '<option value="' . $h['id'] . '">' . e(house_label($h['house_number'])) . '</option>'; echo '</select></div>';
    echo '<div class="field"><label>Reference (optional)</label><input name="reference" maxlength="120"></div><div class="field"><label>Notes (optional)</label><input name="notes" maxlength="500"></div></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-modal-close>Cancel</button><button class="btn btn-primary">Save</button></div></form>';
    modal_end();
}
page_end(['assets/js/vendor/chart.umd.min.js', 'assets/js/charts.js', 'assets/js/finance.js']);
